INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('chest-wall-3-1', '2026.10.2', '{"id":"chest-wall-3-1","unitId":"chest-wall","version":"2026.10.2","mode":3,"difficulty":1,"ordered":true,"briefing":"Chest wall: complete every anatomical station. Fewer cues and a larger required opening. Exterior coverings are prepared for this topic; only your own cut-and-lift actions earn credit.","debrief":"Review missed structures and repeat the activity. Prepared views and chunk extraction are teaching aids, not clinical procedures.","objectives":[{"id":"chest-wall-3-1-0-fma7163-left","title":"Remove a section of skin on the specimen''s left side","instruction":"Scalpel is equipped automatically. Point at skin on the specimen''s left side, hold trigger and sweep a short, continuous cut. Release trigger, grip the separated chunk, lift it clear and release. Continue until this region''s removal meter is full. The remaining tissue stays anchored.","explanation":"A tissue section from skin on the specimen''s left side was cut and lifted. The next prepared station does not imply that all remaining tissue was removed.","targetId":"FMA7163","action":2,"region":"left","narration":"anatomy-chest-wall-3-0-left","toolId":"dissection-scalpel","equipmentState":"chunk-lifted:left","essential":true,"weight":1,"maxDistance":0.04,"maxAngle":20,"minContactSeconds":0,"minPathFraction":0.005,"prerequisites":[]},{"id":"chest-wall-3-1-1-fma7163-right","title":"Remove a section of skin on the specimen''s right side","instruction":"Scalpel is equipped automatically. Point at skin on the specimen''s right side, hold trigger and sweep a short, continuous cut. Release trigger, grip the separated chunk, lift it clear and release. Continue until this region''s removal meter is full. The remaining tissue stays anchored.","explanation":"A tissue section from skin on the specimen''s right side was cut and lifted. The next prepared station does not imply that all remaining tissue was removed.","targetId":"FMA7163","action":2,"region":"right","narration":"anatomy-chest-wall-3-1-right","toolId":"dissection-scalpel","equipmentState":"chunk-lifted:right","essential":true,"weight":1,"maxDistance":0.04,"maxAngle":20,"minContactSeconds":0,"minPathFraction":0.005,"prerequisites":["chest-wall-3-1-0-fma7163-left"]},{"id":"chest-wall-3-1-2-rec_fat-left","title":"Remove a section of Subcutaneous tissue on the specimen''s left side","instruction":"Scalpel is equipped automatically. Point at Subcutaneous tissue on the specimen''s left side, hold trigger and sweep a short, continuous cut. Release trigger, grip the separated chunk, lift it clear and release. Continue until this region''s removal meter is full. The remaining tissue stays anchored.","explanation":"A tissue section from Subcutaneous tissue on the specimen''s left side was cut and lifted. The next prepared station does not imply that all remaining tissue was removed.","targetId":"REC_fat","action":2,"region":"left","narration":"anatomy-chest-wall-3-2-left","toolId":"dissection-scalpel","equipmentState":"chunk-lifted:left","essential":true,"weight":1,"maxDistance":0.04,"maxAngle":20,"minContactSeconds":0,"minPathFraction":0.005,"prerequisites":["chest-wall-3-1-1-fma7163-right"]},{"id":"chest-wall-3-1-3-rec_fat-right","title":"Remove a section of Subcutaneous tissue on the specimen''s right side","instruction":"Scalpel is equipped automatically. Point at Subcutaneous tissue on the specimen''s right side, hold trigger and sweep a short, continuous cut. Release trigger, grip the separated chunk, lift it clear and release. Continue until this region''s removal meter is full. The remaining tissue stays anchored.","explanation":"A tissue section from Subcutaneous tissue on the specimen''s right side was cut and lifted. The next prepared station does not imply that all remaining tissue was removed.","targetId":"REC_fat","action":2,"region":"right","narration":"anatomy-chest-wall-3-3-right","toolId":"d