INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('airways-3-0', '2026.10.2', '{"id":"airways-3-0","unitId":"airways","version":"2026.10.2","mode":3,"difficulty":0,"ordered":true,"briefing":"Airways: complete every anatomical station. Highlighted targets and coached steps. Exterior coverings are prepared for this topic; only your own cut-and-lift actions earn credit.","debrief":"Review missed structures and repeat the activity. Prepared views and chunk extraction are teaching aids, not clinical procedures.","objectives":[{"id":"airways-3-0-0-fma7394-all","title":"Remove a section of trachea","instruction":"Scalpel is equipped automatically. Point at trachea, hold trigger and sweep a short, continuous cut. Release trigger, grip the separated chunk, lift it clear and release. Continue until this region''s removal meter is full. The remaining tissue stays anchored.","explanation":"A tissue section from trachea was cut and lifted. The next prepared station does not imply that all remaining tissue was removed.","targetId":"FMA7394","action":2,"region":"all","narration":"anatomy-airways-3-0-all","toolId":"dissection-scalpel","equipmentState":"chunk-lifted:all","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0.003,"prerequisites":[]},{"id":"airways-3-0-1-fma68418-all","title":"Remove a section of right main bronchus proper","instruction":"Scalpel is equipped automatically. Point at right main bronchus proper, hold trigger and sweep a short, continuous cut. Release trigger, grip the separated chunk, lift it clear and release. Continue until this region''s removal meter is full. The remaining tissue stays anchored.","explanation":"A tissue section from right main bronchus proper was cut and lifted. The next prepared station does not imply that all remaining tissue was removed.","targetId":"FMA68418","action":2,"region":"all","narration":"anatomy-airways-3-1-all","toolId":"dissection-scalpel"