INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('heart-coronaries-3-0', '2026.10.2', '{"id":"heart-coronaries-3-0","unitId":"heart-coronaries","version":"2026.10.2","mode":3,"difficulty":0,"ordered":true,"briefing":"Heart & coronary anatomy: complete every anatomical station. Highlighted targets and coached steps. Exterior coverings are prepared for this topic; only your own cut-and-lift actions earn credit.","debrief":"Review missed structures and repeat the activity. Prepared views and chunk extraction are teaching aids, not clinical procedures.","objectives":[{"id":"heart-coronaries-3-0-0-rec_pericardium-all","title":"Remove a section of Pericardial sac","instruction":"Scalpel is equipped automatically. Point at Pericardial sac, hold trigger and sweep a short, continuous cut. Release trigger, grip the separated chunk, lift it clear and release. Continue until this region''s removal meter is full. The remaining tissue stays anchored.","explanation":"A tissue section from Pericardial sac was cut and lifted. The next prepared station does not imply that all remaining tissue was removed.","targetId":"REC_Pericardium","action":2,"region":"all","narration":"anatomy-heart-coronaries-3-0-all","toolId":"dissection-scalpel","equipmentState":"chunk-lifted:all","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0.003,"prerequisites":[]},{"id":"heart-coronaries-3-0-1-fma9457-all","title":"Identify and preserve wall of right atrium","instruction":"Point at wall of right atrium and press trigger. Examine its relationships and preserve it intact.","explanation":"wall of right atrium examined.","targetId":"FMA9457","action":0,"region":"all","narration":"anatomy-heart-coronaries-3-1-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["heart-coronaries-3-0-0-rec_pericardium-all"]},{"id":"heart-c