INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('vessels-valves-3-0', '2026.10.2', '{"id":"vessels-valves-3-0","unitId":"vessels-valves","version":"2026.10.2","mode":3,"difficulty":0,"ordered":true,"briefing":"Great vessels & valves: complete every anatomical station. Highlighted targets and coached steps. Exterior coverings are prepared for this topic; only your own cut-and-lift actions earn credit.","debrief":"Review missed structures and repeat the activity. Prepared views and chunk extraction are teaching aids, not clinical procedures.","objectives":[{"id":"vessels-valves-3-0-0-fma3736-all","title":"Remove a section of ascending aorta","instruction":"Scalpel is equipped automatically. Point at ascending aorta, hold trigger and sweep a short, continuous cut. Release trigger, grip the separated chunk, lift it clear and release. Continue until this region''s removal meter is full. The remaining tissue stays anchored.","explanation":"A tissue section from ascending aorta was cut and lifted. The next prepared station does not imply that all remaining tissue was removed.","targetId":"FMA3736","action":2,"region":"all","narration":"anatomy-vessels-valves-3-0-all","toolId":"dissection-scalpel","equipmentState":"chunk-lifted:all","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0.003,"prerequisites":[]},{"id":"vessels-valves-3-0-1-fma8612-all","title":"Remove a section of pulmonary trunk","instruction":"Scalpel is equipped automatically. Point at pulmonary trunk, hold trigger and sweep a short, continuous cut. Release trigger, grip the separated chunk, lift it clear and release. Continue until this region''s removal meter is full. The remaining tissue stays anchored.","explanation":"A tissue section from pulmonary trunk was cut and lifted. The next prepared station does not imply that all remaining tissue was removed.","targetId":"FMA8612","action":2,"region":"all","narration":"anatomy-vessels-valves-3-1-all","toolId":"dissection-scalpel","equipmentState":"chunk-lifted:all","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0.003,"prerequisites":["vessels-valves-3-0-0-fma3736-all"]},{"id":"vessels-valves-3-0-2-fma3768-all","title":"Identify and preserve arch of aorta","instruction":"Point at arch of aorta and press trigger. Examine its relationships and preserve it intact.","explanation":"arch of aorta examined.","targetId":"FMA3768","action":0,"region":"all","narration":"anatomy-vessels-valves-3-2-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["vessels-valves-3-0-1-fma8612-all"]},{"id":"vessels-valves-3-0-3-fma50872-all","title":"Identify and preserve right pulmonary artery","instruction":"Point at right pulmonary artery and press trigger. Examine its relationships and preserve it intact.","explanation":"right pulmonary artery examined.","targetId":"FMA50872","action":0,"region":"all","narration":"anatomy-vessels-valves-3-3-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["vessels-valves-3-0-2-fma3768-all"]},{"id":"vessels-valves-3-0-4-fma50873-all","title":"Identify and preserve left pulmonary artery","instruction":"Point at left pulmonary artery and press trigger. Examine its relationships and preserve it intact.","explanation":"left pulmonary artery examined.","targetId":"FMA50873","action":0,"region":"all","narration":"anatomy-vessels-valves-3-4-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["vessels-valves-3-0-3-fma50872-all"]},{"id":"vessels-valves-3-0-5-fma7252-all","title":"Identify and preserve right posterior cusp of aortic valve","instruction":"Point at right posterior cusp of aortic valve and press trigger. Examine its relationships and preserve it intact.","explanation":"right posterior cusp of aortic valve examined.","targetId":"FMA7252","action":0,"region":"all","narration":"anatomy-vessels-valves-3-5-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["vessels-valves-3-0-4-fma50873-all"]},{"id":"vessels-valves-3-0-6-fma7253-all","title":"Identify and preserve anterior cusp of aortic valve","instruction":"Point at anterior cusp of aortic valve and press trigger. Examine its relationships and preserve it intact.","explanation":"anterior cusp of aortic valve examined.","targetId":"FMA7253","action":0,"region":"all","narration":"anatomy-vessels-valves-3-6-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["vessels-valves-3-0-5-fma7252-all"]},{"id":"vessels-valves-3-0-7-fma7254-all","title":"Identify and preserve left posterior cusp of aortic valve","instruction":"Point at left posterior cusp of aortic valve and press trigger. Examine its relationships and preserve it intact.","explanation":"left posterior cusp of aortic valve examined.","targetId":"FMA7254","action":0,"region":"all","narration":"anatomy-vessels-valves-3-7-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["vessels-valves-3-0-6-fma7253-all"]}],"protectedIds":["FMA50040"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
