INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('mediastinum-3-0', '2026.10.2', '{"id":"mediastinum-3-0","unitId":"mediastinum","version":"2026.10.2","mode":3,"difficulty":0,"ordered":true,"briefing":"Mediastinal relationships: complete every anatomical station. Highlighted targets and coached steps. Exterior coverings are prepared for this topic; only your own cut-and-lift actions earn credit.","debrief":"Review missed structures and repeat the activity. Prepared views and chunk extraction are teaching aids, not clinical procedures.","objectives":[{"id":"mediastinum-3-0-0-fma7131-all","title":"Remove a section of esophagus","instruction":"Scalpel is equipped automatically. Point at esophagus, hold trigger and sweep a short, continuous cut. Release trigger, grip the separated chunk, lift it clear and release. Continue until this region''s removal meter is full. The remaining tissue stays anchored.","explanation":"A tissue section from esophagus was cut and lifted. The next prepared station does not imply that all remaining tissue was removed.","targetId":"FMA7131","action":2,"region":"all","narration":"anatomy-mediastinum-3-0-all","toolId":"dissection-scalpel","equipmentState":"chunk-lifted:all","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0.003,"prerequisites":[]},{"id":"mediastinum-3-0-1-rec_right_phrenic_nerve-all","title":"Identify and preserve Right phrenic nerve","instruction":"Point at Right phrenic nerve and press trigger. Examine its relationships and preserve it intact.","explanation":"Right phrenic nerve examined.","targetId":"REC_Right_Phrenic_nerve","action":0,"region":"all","narration":"anatomy-mediastinum-3-1-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-0-0-fma7131-all"]},{"id":"mediastinum-3-0-2-rec_left_phrenic_nerve-all","title":"Iden