tial":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-0-4-rec_left_vagus_nerve-all"]},{"id":"mediastinum-3-0-6-fma87217-all","title":"Identify and preserve descending thoracic aorta","instruction":"Point at descending thoracic aorta and press trigger. Examine its relationships and preserve it intact.","explanation":"descending thoracic aorta examined.","targetId":"FMA87217","action":0,"region":"all","narration":"anatomy-mediastinum-3-6-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-0-5-rec_thoracicduct-all"]},{"id":"mediastinum-3-0-7-fma7394-all","title":"Identify and preserve trachea","instruction":"Point at trachea and press trigger. Examine its relationships and preserve it intact.","explanation":"trachea examined.","targetId":"FMA7394","action":0,"region":"all","narration":"anatomy-mediastinum-3-7-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-0-6-fma87217-all"]}],"protectedIds":["FMA50040"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('mediastinum-3-1', '2026.10.2', '{"id":"mediastinum-3-1","unitId":"mediastinum","version":"2026.10.2","mode":3,"difficulty":1,"ordered":true,"briefing":"Mediastinal relationships: complete every anatomical station. Fewer cues and a larger required opening. Exterior coverings are prepared for this topic; only your own cut-and-lift actions earn credit.","debrief":"Review missed structures and repeat the activity. Prepared views and chunk extraction are teaching aids, not clinical procedures.","objectives":[{"id":"mediastinum-3-1-0-fma7131-all","title":"Remove a section of esophagus","instruction":"Scalpel is equipped automatically. Point at esophagus, hold trigger and sweep a short, continuous cut. Release trigger, grip the separated chunk, lift it clear and release. Continue until this region''s removal meter is full. The remaining tissue stays anchored.","explanation":"A tissue section from esophagus was cut and lifted. The next prepared station does not imply that all remaining tissue was removed.","targetId":"FMA7131","action":2,"region":"all","narration":"anatomy-mediastinum-3-0-all","toolId":"dissection-scalpel","equipmentState":"chunk-lifted:all","essential":true,"weight":1,"maxDistance":0.04,"maxAngle":20,"minContactSeconds":0,"minPathFraction":0.005,"prerequisites":[]},{"id":"mediastinum-3-1-1-rec_right_phrenic_nerve-all","title":"Identify and preserve Right phrenic nerve","instruction":"Point at Right phrenic nerve and press trigger. Examine its relationships and preserve it intact.","explanation":"Right phrenic nerve examined.","targetId":"REC_Right_Phrenic_nerve","action":0,"region":"all","narration":"anatomy-mediastinum-3-1-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.04,"maxAngle":20,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-1-0-fma7131-all"]},{"id":"mediastinum-3-1-2-rec_left_phrenic_nerve-all","title":"Identify and preserve Left phrenic nerve","instruction":"Point at Left phrenic nerve and press trigger. Examine its relationships and preserve it intact.","explanation":"Left phrenic nerve examined.","targetId":"REC_Left_Phrenic_nerve","action":0,"region":"all","narration":"anatomy-mediastinum-3-2-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.04,"maxAngle":20,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-1-1-rec_right_phrenic_nerve-all"]},{"id":"mediastinum-3-1-3-rec_right_vagus_nerve-all","title":"Identify and preserve Right vagus nerve","instruction":"Point at Right vagus nerve and press trigger. Examine its relationships and preserve it intact.","explanation":"Right vagus nerve examined.","targetId":"REC_Right_Vagus_nerve","action":0,"region":"all","narration":"anatomy-mediastinum-3-3-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.04,"maxAngle":20,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-1-2-rec_left_phrenic_nerve-all"]},{"id":"mediastinum-3-1-4-rec_left_vagus_nerve-all","title":"Identify and preserve Left vagus nerve","instruction":"Point at Left vagus nerve and press trigger. Examine its relationships and preserve it intact.","explanation":"Left vagus nerve examined.","targetId":"REC_Left_Vagus_nerve","action":0,"region":"all","narration":"anatomy-mediastinum-3-4-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.04,"maxAngle":20,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-1-3-rec_right_vagus_nerve-all"]},{"id":"mediastinum-3-1-5-rec_thoracicduct-all","title":"Identify and preserve Thoracic duct","instruction":"Point at Thoracic duct and press trigger. Examine its relationships and preserve it intact.","explanation":"Thoracic duct examined.","targetId":"REC_ThoracicDuct","action":0,"region":"all","narration":"anatomy-mediastinum-3-5-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.04,"maxAngle":20,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-1-4-rec_left_vagus_nerve-all"]},{"id":"mediastinum-3-1-6-fma87217-all","title":"Identify and preserve descending thoracic aorta","instruction":"Point at descending thoracic aorta and press trigger. Examine its relationships and preserve it intact.","explanation":"descending thoracic aorta examined.","targetId":"FMA87217","action":0,"region":"all","narration":"anatomy-mediastinum-3-6-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.04,"maxAngle":20,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-1-5-rec_thoracicduct-all"]},{"id":"mediastinum-3-1-7-fma7394-all","title":"Identify and preserve trachea","instruction":"Point at trachea and press trigger. Examine its relationships and preserve it intact.","explanation":"trachea examined.","targetId":"FMA7394","action":0,"region":"all","narration":"anatomy-mediastinum-3-7-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.04,"maxAngle":20,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-1-6-fma87217-all"]}],"protectedIds":["FMA50040"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('mediastinum-3-2', '2026.10.2', '{"id":"mediastinum-3-2","unitId":"mediastinum","version":"2026.10.2","mode":3,"difficulty":2,"ordered":true,"briefing":"Mediastinal relationships: complete every anatomical station. Independent work with the strictest removal requirement. Exterior coverings are prepared for this topic; only your own cut-and-lift actions earn credit.","debrief":"Review missed structures and repeat the activity. Prepared views and chunk extraction are teaching aids, not clinical procedures.","objectives":[{"id":"mediastinum-3-2-0-fma7131-all","title":"Remove a section of esophagus","instruction":"Scalpel is equipped automatically. Point at esophagus, hold trigger and sweep a short, continuous cut. Release trigger, grip the separated chunk, lift it clear and release. Continue until this region''s removal meter is full. The remaining tissue stays anchored.","explanation":"A tissue section from esophagus was cut and lifted. The next prepared station does not imply that all remaining tissue was removed.","targetId":"FMA7131","action":2,"region":"all","narration":"anatomy-mediastinum-3-0-all","toolId":"dissection-scalpel","equipmentState":"chunk-lifted:all","essential":true,"weight":1,"maxDistance":0.02,"maxAngle":10,"minContactSeconds":0,"minPathFraction":0.008,"prerequisites":[]},{"id":"mediastinum-3-2-1-rec_right_phrenic_nerve-all","title":"Identify and preserve Right phrenic nerve","instruction":"Point at Right phrenic nerve and press trigger. Examine its relationships and preserve it intact.","explanation":"Right phrenic nerve examined.","targetId":"REC_Right_Phrenic_nerve","action":0,"region":"all","narration":"anatomy-mediastinum-3-1-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.02,"maxAngle":10,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-2-0-fma7131-all"]},{"id":"mediastinum-3-2-2-rec_left_phrenic_nerve-all","title":"Identify and preserve Left phrenic nerve","instruction":"Point at Left phrenic nerve and press trigger. Examine its relationships and preserve it intact.","explanation":"Left phrenic nerve examined.","targetId":"REC_Left_Phrenic_nerve","action":0,"region":"all","narration":"anatomy-mediastinum-3-2-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.02,"maxAngle":10,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-2-1-rec_right_phrenic_nerve-all"]},{"id":"mediastinum-3-2-3-rec_right_vagus_nerve-all","title":"Identify and preserve Right vagus nerve","instruction":"Point at Right vagus nerve and press trigger. Examine its relationships and preserve it intact.","explanation":"Right vagus nerve examined.","targetId":"REC_Right_Vagus_nerve","action":0,"region":"all","narration":"anatomy-mediastinum-3-3-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.02,"maxAngle":10,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-2-2-rec_left_phrenic_nerve-all"]},{"id":"mediastinum-3-2-4-rec_left_vagus_nerve-all","title":"Identify and preserve Left vagus nerve","instruction":"Point at Left vagus nerve and press trigger. Examine its relationships and preserve it intact.","explanation":"Left vagus nerve examined.","targetId":"REC_Left_Vagus_nerve","action":0,"region":"all","narration":"anatomy-mediastinum-3-4-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.02,"maxAngle":10,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-2-3-rec_right_vagus_nerve-all"]},{"id":"mediastinum-3-2-5-rec_thoracicduct-all","title":"Identify and preserve Thoracic duct","instruction":"Point at Thoracic duct and press trigger. Examine its relationships and preserve it intact.","explanation":"Thoracic duct examined.","targetId":"REC_ThoracicDuct","action":0,"region":"all","narration":"anatomy-mediastinum-3-5-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.02,"maxAngle":10,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-2-4-rec_left_vagus_nerve-all"]},{"id":"mediastinum-3-2-6-fma87217-all","title":"Identify and preserve descending thoracic aorta","instruction":"Point at descending thoracic aorta and press trigger. Examine its relationships and preserve it intact.","explanation":"descending thoracic aorta examined.","targetId":"FMA87217","action":0,"region":"all","narration":"anatomy-mediastinum-3-6-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.02,"maxAngle":10,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-2-5-rec_thoracicduct-all"]},{"id":"mediastinum-3-2-7-fma7394-all","title":"Identify and preserve trachea","instruction":"Point at trachea and press trigger. Examine its relationships and preserve it intact.","explanation":"trachea examined.","targetId":"FMA7394","action":0,"region":"all","narration":"anatomy-mediastinum-3-7-all","toolId":"","equipmentState":"","essential":true,"weight":1,"maxDistance":0.02,"maxAngle":10,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["mediastinum-3-2-6-fma87217-all"]}],"protectedIds":["FMA50040"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('pneumothorax-0-0', '2026.10.2', '{"id":"pneumothorax-0-0","unitId":"pneumothorax","version":"2026.10.2","mode":0,"difficulty":0,"ordered":true,"briefing":"A breathless adult has a right pneumothorax. The case team has selected a small-bore chest drain. One coached step and one needed instrument are shown at a time.","debrief":"Air drains through the connected water seal. Recheck breathing, drain function and chest imaging; watch for pain, bleeding, infection or renewed breathlessness. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the collapsed lung","instruction":"Point to the right superior lobe. Compare its size with the opposite lung.","targetId":"MAL_RUL","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-3-mal_rul-hand-0","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"pneumothorax-step-0"},{"title":"Explain the anatomical mechanism","instruction":"Inspect the specimen and three cutaways. Grip the mechanism that explains this case and release it into the patient-plan dock.","targetId":"equipment:reason-mechanism","action":10,"toolId":"mechanism:pneumothorax","equipmentState":"placed","choices":[{"id":"mechanism:pneumothorax","label":"Pleural air","model":"pneumothorax","response":0,"rationale":"Compare this cutaway with the observed anatomy. Air in the pleural space separates the lung from the chest wall."},{"id":"mechanism:pleural-effusion","label":"Pleural fluid","model":"pleural-effusion","response":0,"rationale":"Compare this cutaway with the observed anatomy. Fluid outside the lung compresses its surrounding pleural compartment."},{"id":"mechanism:pneumonia","label":"Inflamed air spaces","model":"pneumonia","response":0,"rationale":"Compare this cutaway with the observed anatomy. Inflammatory material occupies affected alveolar air spaces."}],"explanation":"Air in the pleural space separates the lung from the chest wall.","criticalOnWrong":false,"id":"pneumothorax-0-0-10-equipment-reason-mechanism-mechanism:pneumothorax-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-3-mal_rul-hand-0"],"narration":"pneumothorax-step-1"},{"title":"Check the patient and plan","instruction":"The chest image and indication are already established. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-10-equipment-reason-mechanism-mechanism:pneumothorax-0"],"narration":"pneumothorax-step-2"},{"title":"Check the planned intercostal space","instruction":"Locate the upper edge of the lower rib on the cross-section. Avoid the bundle beneath the rib above.","targetId":"equipment:pleural-site","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-5-equipment-pleural-site-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-5-equipment-chart-probe-0"],"narration":"pneumothorax-step-3"},{"title":"Prepare a sterile field","instruction":"Move the swab onto the marked skin window. Hold the trigger to clean it; the sterile drape opens.","targetId":"equipment:pleural-site","action":6,"toolId":"swab","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-6-equipment-pleural-site-swab-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-5-equipment-pleural-site-probe-0"],"narration":"pneumothorax-step-4"},{"title":"Represent local anaesthesia","instruction":"Place the anaesthetic syringe at the skin target. The case supplies the checked prescription.","targetId":"equipment:pleural-site","action":6,"toolId":"anaesthetic","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-6-equipment-pleural-site-anaesthetic-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-6-equipment-pleural-site-swab-0"],"narration":"pneumothorax-step-5"},{"title":"Confirm pleural access","instruction":"Guide the aspiration needle to the pleural-space endpoint. Air appears in the syringe before the wire step opens.","targetId":"equipment:pleural-end","action":5,"toolId":"needle","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-5-equipment-pleural-end-needle-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-6-equipment-pleural-site-anaesthetic-0"],"narration":"pneumothorax-step-6"},{"title":"Advance the guidewire","instruction":"Move the wire through each marker into the air space. Preserve the lung beyond the endpoint.","targetId":"equipment:pleural-end","action":7,"toolId":"guidewire","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-7-equipment-pleural-end-guidewire-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-0-5-equipment-pleural-end-needle-0"],"narration":"pneumothorax-step-7"},{"title":"Make the skin opening","instruction":"Move the scalpel along the short skin line beside the retained wire.","targetId":"equipment:pleural-incision","action":7,"toolId":"scalpel","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-7-equipment-pleural-incision-scalpel-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-0-7-equipment-pleural-end-guidewire-0"],"narration":"pneumothorax-step-8"},{"title":"Open the drain tract","instruction":"Advance the short dilator along the wire route. Stop at the endpoint; do not push toward the lung.","targetId":"equipment:pleural-end","action":7,"toolId":"dilator","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-7-equipment-pleural-end-dilator-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-0-7-equipment-pleural-incision-scalpel-0"],"narration":"pneumothorax-step-9"},{"title":"Place the drain over the wire","instruction":"Follow the same route with the drain. The training model then withdraws the wire and retains the drain.","targetId":"equipment:pleural-end","action":7,"toolId":"drain","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-7-equipment-pleural-end-drain-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-0-7-equipment-pleural-end-dilator-0"],"narration":"pneumothorax-step-10"},{"title":"Connect the water seal","instruction":"Fit the connector into the drain-bottle port. Keep the bottle below the chest.","targetId":"equipment:drain-circuit","action":4,"toolId":"connector","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-4-equipment-drain-circuit-connector-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-7-equipment-pleural-end-drain-0"],"narration":"pneumothorax-step-11"},{"title":"Fix the holding suture","instruction":"Follow the fixation loop around the drain with the needle holder. The holding suture secures the tube.","targetId":"equipment:pleural-fixation","action":7,"toolId":"suture","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-7-equipment-pleural-fixation-suture-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-0-4-equipment-drain-circuit-connector-0"],"narration":"pneumothorax-step-12"},{"title":"Secure the drain","instruction":"Place the fixation dressing over the entry site. Confirm the tube is secured.","targetId":"equipment:pleural-site","action":6,"toolId":"dressing","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-6-equipment-pleural-site-dressing-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-7-equipment-pleural-fixation-suture-0"],"narration":"pneumothorax-step-13"},{"title":"Predict the structural response","instruction":"Before reassessing the patient, place the cutaway showing the expected anatomical response in the dock. Model changes are illustrative; improvement does not prove clinical recovery.","targetId":"equipment:reason-response","action":10,"toolId":"response:improved","equipmentState":"placed","choices":[{"id":"response:improved","label":"Lung re-expands","model":"pneumothorax","response":1,"rationale":"The represented treatment addresses this anatomical mechanism."},{"id":"response:unchanged","label":"Unchanged anatomy","model":"pneumothorax","response":0,"rationale":"An unchanged model does not show the intended structural response. Reassess the mechanism and treatment."},{"id":"response:other","label":"Narrowed airway","model":"asthma","response":1,"rationale":"This is a different compartment or mechanism. Match the response to the anatomy actually treated."}],"explanation":"The model shows the intended anatomical change. Clinical benefit and complications still require reassessment.","criticalOnWrong":false,"id":"pneumothorax-0-0-10-equipment-reason-response-response:improved-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-6-equipment-pleural-site-dressing-0"],"narration":"pneumothorax-step-14"},{"title":"Check the response","instruction":"Touch the affected lobe with the assessment pointer. Inspect expansion and the connected drain.","targetId":"MAL_RUL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-8-mal_rul-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-10-equipment-reason-response-response:improved-0"],"narration":"pneumothorax-step-15"}],"protectedIds":["REC_Right_IC4_Nerve","REC_Right_IC4_Artery","FMA13295","MAL_RLL"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('pneumothorax-0-1', '2026.10.2', '{"id":"pneumothorax-0-1","unitId":"pneumothorax","version":"2026.10.2","mode":0,"difficulty":1,"ordered":true,"briefing":"A breathless adult has a right pneumothorax. The case team has selected a small-bore chest drain. Use the findings to plan the sequence; most placement cues are removed.","debrief":"Air drains through the connected water seal. Recheck breathing, drain function and chest imaging; watch for pain, bleeding, infection or renewed breathlessness. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the collapsed lung","instruction":"Point to the right superior lobe. Compare its size with the opposite lung.","targetId":"MAL_RUL","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-3-mal_rul-hand-0","essential":true,"weight":1,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"pneumothorax-step-0"},{"title":"Explain the anatomical mechanism","instruction":"Inspect the specimen and three cutaways. Grip the mechanism that explains this case and release it into the patient-plan dock.","targetId":"equipment:reason-mechanism","action":10,"toolId":"mechanism:pneumothorax","equipmentState":"placed","choices":[{"id":"mechanism:pneumothorax","label":"Pleural air","model":"pneumothorax","response":0,"rationale":"Compare this cutaway with the observed anatomy. Air in the pleural space separates the lung from the chest wall."},{"id":"mechanism:pleural-effusion","label":"Pleural fluid","model":"pleural-effusion","response":0,"rationale":"Compare this cutaway with the observed anatomy. Fluid outside the lung compresses its surrounding pleural compartment."},{"id":"mechanism:pneumonia","label":"Inflamed air spaces","model":"pneumonia","response":0,"rationale":"Compare this cutaway with the observed anatomy. Inflammatory material occupies affected alveolar air spaces."}],"explanation":"Air in the pleural space separates the lung from the chest wall.","criticalOnWrong":false,"id":"pneumothorax-0-1-10-equipment-reason-mechanism-mechanism:pneumothorax-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["pneumothorax-0-1-3-mal_rul-hand-0"],"narration":"pneumothorax-step-1"},{"title":"Check the patient and plan","instruction":"The chest image and indication are already established. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumothorax-0-1-10-equipment-reason-mechanism-mechanism:pneumothorax-0"],"narration":"pneumothorax-step-2"},{"title":"Check the planned intercostal space","instruction":"Locate the upper edge of the lower rib on the cross-section. Avoid the bundle beneath the rib above.","targetId":"equipment:pleural-site","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-5-equipment-pleural-site-probe-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumothorax-0-1-5-equipment-chart-probe-0"],"narration":"pneumothorax-step-3"},{"title":"Prepare a sterile field","instruction":"Move the swab onto the marked skin window. Hold the trigger to clean it; the sterile drape opens.","targetId":"equipment:pleural-site","action":6,"toolId":"swab","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-6-equipment-pleural-site-swab-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumothorax-0-1-5-equipment-pleural-site-probe-0"],"narration":"pneumothorax-step-4"},{"title":"Represent local anaesthesia","instruction":"Place the anaesthetic syringe at the skin target. The case supplies the checked prescription.","targetId":"equipment:pleural-site","action":6,"toolId":"anaesthetic","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-6-equipment-pleural-site-anaesthetic-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumothorax-0-1-6-equipment-pleural-site-swab-0"],"narration":"pneumothorax-step-5"},{"title":"Confirm pleural access","instruction":"Guide the aspiration needle to the pleural-space endpoint. Air appears in the syringe before the wire step opens.","targetId":"equipment:pleural-end","action":5,"toolId":"needle","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-5-equipment-pleural-end-needle-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumothorax-0-1-6-equipment-pleural-site-anaesthetic-0"],"narration":"pneumothorax-step-6"},{"title":"Advance the guidewire","instruction":"Move the wire through each marker into the air space. Preserve the lung beyond the endpoint.","targetId":"equipment:pleural-end","action":7,"toolId":"guidewire","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-7-equipment-pleural-end-guidewire-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-1-5-equipment-pleural-end-needle-0"],"narration":"pneumothorax-step-7"},{"title":"Make the skin opening","instruction":"Move the scalpel along the short skin line beside the retained wire.","targetId":"equipment:pleural-incision","action":7,"toolId":"scalpel","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-7-equipment-pleural-incision-scalpel-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-1-7-equipment-pleural-end-guidewire-0"],"narration":"pneumothorax-step-8"},{"title":"Open the drain tract","instruction":"Advance the short dilator along the wire route. Stop at the endpoint; do not push toward the lung.","targetId":"equipment:pleural-end","action":7,"toolId":"dilator","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-7-equipment-pleural-end-dilator-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-1-7-equipment-pleural-incision-scalpel-0"],"narration":"pneumothorax-step-9"},{"title":"Place the drain over the wire","instruction":"Follow the same route with the drain. The training model then withdraws the wire and retains the drain.","targetId":"equipment:pleural-end","action":7,"toolId":"drain","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-7-equipment-pleural-end-drain-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-1-7-equipment-pleural-end-dilator-0"],"narration":"pneumothorax-step-10"},{"title":"Connect the water seal","instruction":"Fit the connector into the drain-bottle port. Keep the bottle below the chest.","targetId":"equipment:drain-circuit","action":4,"toolId":"connector","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-4-equipment-drain-circuit-connector-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumothorax-0-1-7-equipment-pleural-end-drain-0"],"narration":"pneumothorax-step-11"},{"title":"Fix the holding suture","instruction":"Follow the fixation loop around the drain with the needle holder. The holding suture secures the tube.","targetId":"equipment:pleural-fixation","action":7,"toolId":"suture","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-7-equipment-pleural-fixation-suture-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-1-4-equipment-drain-circuit-connector-0"],"narration":"pneumothorax-step-12"},{"title":"Secure the drain","instruction":"Place the fixation dressing over the entry site. Confirm the tube is secured.","targetId":"equipment:pleural-site","action":6,"toolId":"dressing","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-6-equipment-pleural-site-dressing-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumothorax-0-1-7-equipment-pleural-fixation-suture-0"],"narration":"pneumothorax-step-13"},{"title":"Predict the structural response","instruction":"Before reassessing the patient, place the cutaway showing the expected anatomical response in the dock. Model changes are illustrative; improvement does not prove clinical recovery.","targetId":"equipment:reason-response","action":10,"toolId":"response:improved","equipmentState":"placed","choices":[{"id":"response:improved","label":"Lung re-expands","model":"pneumothorax","response":1,"rationale":"The represented treatment addresses this anatomical mechanism."},{"id":"response:unchanged","label":"Unchanged anatomy","model":"pneumothorax","response":0,"rationale":"An unchanged model does not show the intended structural response. Reassess the mechanism and treatment."},{"id":"response:other","label":"Narrowed airway","model":"asthma","response":1,"rationale":"This is a different compartment or mechanism. Match the response to the anatomy actually treated."}],"explanation":"The model shows the intended anatomical change. Clinical benefit and complications still require reassessment.","criticalOnWrong":false,"id":"pneumothorax-0-1-10-equipment-reason-response-response:improved-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["pneumothorax-0-1-6-equipment-pleural-site-dressing-0"],"narration":"pneumothorax-step-14"},{"title":"Check the response","instruction":"Touch the affected lobe with the assessment pointer. Inspect expansion and the connected drain.","targetId":"MAL_RUL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-8-mal_rul-probe-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumothorax-0-1-10-equipment-reason-response-response:improved-0"],"narration":"pneumothorax-step-15"}],"protectedIds":["REC_Right_IC4_Nerve","REC_Right_IC4_Artery","FMA13295","MAL_RLL"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
