INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('coronary-disease-0-0', '2026.10.2', '{"id":"coronary-disease-0-0","unitId":"coronary-disease","version":"2026.10.2","mode":0,"difficulty":0,"ordered":true,"briefing":"A coronary lesion has been selected for PCI after assessment. Follow a radial-access balloon and stent case. One coached step and one needed instrument are shown at a time.","debrief":"Final vessel imaging shows the treated lumen. Check the wrist for bleeding and continue the prescribed coronary and antiplatelet care; stenting does not cure the underlying disease. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the affected coronary artery","instruction":"Select the left coronary artery. Inspect the plaque in the enlarged cutaway.","targetId":"FMA50040","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"coronary-disease-0-0-3-fma50040-hand-0","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"coronary-disease-step-0"},{"title":"Explain the anatomical mechanism","instruction":"Inspect the specimen and three cutaways. Grip the mechanism that explains this case and release it into the patient-plan dock.","targetId":"equipment:reason-mechanism","action":10,"toolId":"mechanism:coronary-disease","equipmentState":"placed","choices":[{"id":"mechanism:coronary-disease","label":"Narrowed coronary lumen","model":"coronary-disease","response":0,"rationale":"Compare this cutaway with the observed anatomy. Coronary plaque limits the vessel lumen and myocardial blood supply."},{"id":"mechanism:aortic-stenosis","label":"Restricted valve opening","model":"aortic-stenosis","response":0,"rationale":"Compare this cutaway with the observed anatomy. Restricted aortic cusps obstruct forward flow from the left ventricle."},{"id":"mechanism:pleural-effusion","label":"Pleural fluid","model":"pleural-effusion","response":0,"rationale":"Compare this cutaway with the observed anatomy. Fluid outside the lung compresses its surrounding pleural compartment."}],"explanation":"Coronary plaque limits the vessel lumen and myocardial blood supply.","criticalOnWrong":false,"id":"coronary-disease-0-0-10-equipment-reason-mechanism-mechanism:coronary-disease-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-3-fma50040-hand-0"],"narration":"coronary-disease-step-1"},{"title":"Check the patient and plan","instruction":"Review the angiogram, selected lesion and contrast history. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"coronary-disease-0-0-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-10-equipment-reason-mechanism-mechanism:coronary-disease-0"],"narration":"coronary-disease-step-2"},{"title":"Prepare radial access","instruction":"Use the swab on the wrist target of the enlarged vascular model. Local anaesthesia and access checks are represented.","targetId":"equipment:radial-access","action":6,"toolId":"swab","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"coronary-disease-0-0-6-equipment-radial-access-swab-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-5-equipment-chart-probe-0"],"narration":"coronary-disease-step-3"},{"title":"Connect the guiding catheter","instruction":"Seat the catheter connector in the access sheath port.","targetId":"equipment:catheter-system","action":4,"toolId":"connector","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"coronary-disease-0-0-4-equipment-catheter-system-connector-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-6-equipment-radial-access-swab-0"],"narration":"coronary-disease-step-4"},{"title":"Follow the arterial route","instruction":"Follow right radial, brachial, axillary, subclavian, brachiocephalic and aortic markers to the coronary origin.","targetId":"equipment:coronary-origin","action":7,"toolId":"guidewire","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"coronary-disease-0-0-7-equipment-coronary-origin-guidewire-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["coronary-disease-0-0-4-equipment-catheter-system-connector-0"],"narration":"coronary-disease-step-5"},{"title":"Cross the selected lesion","instruction":"Follow the coronary channel through the narrowing. Stop at the wire endpoint.","targetId":"equipment:coronary-lesion","action":7,"toolId":"guidewire","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"coronary-disease-0-0-7-equipment-coronary-lesion-guidewire-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["coronary-disease-0-0-7-equipment-coronary-origin-guidewire-0"],"narration":"coronary-disease-step-6"},{"title":"Place the balloon","instruction":"Align the balloon within the lesion over the represented wire.","targetId":"equipment:coronary-lesion","action":5,"toolId":"balloon","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"coronary-disease-0-0-5-equipment-coronary-lesion-balloon-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-7-equipment-coronary-lesion-guidewire-0"],"narration":"coronary-disease-step-7"},{"title":"Dilate the selected lesion","instruction":"Activate the balloon. Watch it expand, then deflate before advancing.","targetId":"equipment:coronary-lesion","action":6,"toolId":"balloon","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"coronary-disease-0-0-6-equipment-coronary-lesion-balloon-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-5-equipment-coronary-lesion-balloon-0"],"narration":"coronary-disease-step-8"},{"title":"Deploy the stent","instruction":"Position the stent at the same lesion and activate. The scaffold remains in the artery.","targetId":"equipment:coronary-lesion","action":6,"toolId":"stent","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"coronary-disease-0-0-6-equipment-coronary-lesion-stent-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-6-equipment-coronary-lesion-balloon-0"],"narration":"coronary-disease-step-9"},{"title":"Withdraw the delivery device","instruction":"Move the catheter back along the withdrawal markers. The stent stays in place.","targetId":"equipment:catheter-withdrawal","action":7,"toolId":"balloon","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"coronary-disease-0-0-7-equipment-catheter-withdrawal-balloon-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["coronary-disease-0-0-6-equipment-coronary-lesion-stent-0"],"narration":"coronary-disease-step-10"},{"title":"Close the access site","instruction":"Fit the compression band around the radial access model.","targetId":"equipment:radial-access","action":6,"toolId":"dressing","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"coronary-disease-0-0-6-equipment-radial-access-dressing-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-7-equipment-catheter-withdrawal-balloon-0"],"narration":"coronary-disease-step-11"},{"title":"Predict the structural response","instruction":"Before reassessing the patient, place the cutaway showing the expected anatomical response in the dock. Model changes are illustrative; improvement does not prove clinical recovery.","targetId":"equipment:reason-response","action":10,"toolId":"response:improved","equipmentState":"placed","choices":[{"id":"response:improved","label":"Wider treated lumen","model":"coronary-disease","response":1,"rationale":"The represented treatment addresses this anatomical mechanism."},{"id":"response:unchanged","label":"Unchanged anatomy","model":"coronary-disease","response":0,"rationale":"An unchanged model does not show the intended structural response. Reassess the mechanism and treatment."},{"id":"response:other","label":"Pleural air","model":"pneumothorax","response":1,"rationale":"This is a different compartment or mechanism. Match the response to the anatomy actually treated."}],"explanation":"The model shows the intended anatomical change. Clinical benefit and complications still require reassessment.","criticalOnWrong":false,"id":"coronary-disease-0-0-10-equipment-reason-response-response:improved-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-6-equipment-radial-access-dressing-0"],"narration":"coronary-disease-step-12"},{"title":"Review final flow","instruction":"Probe the left coronary artery. Compare the lumen and review the follow-up plan.","targetId":"FMA50040","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"coronary-disease-0-0-8-fma50040-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-10-equipment-reason-response-response:improved-0"],"narration":"coronary-disease-step-13"}],"protectedIds":["FMA7252","FMA7253","FMA7254"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
