neumonia-step-9"},{"title":"Review the follow-up timeline","instruction":"Probe the affected lobe. Watch the days-and-weeks timeline; recovery is gradual.","targetId":"MAL_RLL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-1-8-mal_rll-probe-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumonia-0-1-10-equipment-reason-response-response:improved-0"],"narration":"pneumonia-step-10"}],"protectedIds":["REC_Right_Phrenic_nerve"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('pneumonia-0-2', '2026.10.2', '{"id":"pneumonia-0-2","unitId":"pneumonia","version":"2026.10.2","mode":0,"difficulty":2,"ordered":true,"briefing":"An adult has confirmed bacterial pneumonia, prescribed antibiotics and an oxygen order for hypoxaemia. Work independently, identify unsafe actions and reassess the response.","debrief":"Review response and microbiology. Review intravenous treatment by 48 hours. Fever often settles before cough and fatigue; persistent or worsening symptoms need reassessment. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the affected lobe","instruction":"Select the right inferior lobe. Compare air spaces with the clear neighboring tissue.","targetId":"MAL_RLL","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-2-3-mal_rll-hand-0","essential":true,"weight":1,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"pneumonia-step-0"},{"title":"Explain the anatomical mechanism","instruction":"Inspect the specimen and three cutaways. Grip the mechanism that explains this case and release it into the patient-plan dock.","targetId":"equipment:reason-mechanism","action":10,"toolId":"mechanism:pneumonia","equipmentState":"placed","choices":[{"id":"mechanism:pneumonia","label":"Inflamed air spaces","model":"pneumonia","response":0,"rationale":"Compare this cutaway with the observed anatomy. Inflammatory material occupies affected alveolar air spaces."},{"id":"mechanism:coronary-disease","label":"Narrowed coronary lumen","model":"coronary-disease","response":0,"rationale":"Compare this cutaway with the observed anatomy. Coronary plaque limits the vessel lumen and myocardial blood supply."},{"id":"mechanism:pneumothorax","label":"Pleural air","model":"pneumothorax","response":0,"rationale":"Compare this cutaway with the observed anatomy. Air in the pleural space separates the lung from the chest wall."}],"explanation":"Inflammatory material occupies affected alveolar air spaces.","criticalOnWrong":false,"id":"pneumonia-0-2-10-equipment-reason-mechanism-mechanism:pneumonia-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["pneumonia-0-2-3-mal_rll-hand-0"],"narration":"pneumonia-step-1"},{"title":"Check the patient and plan","instruction":"Review severity, allergies and the written antibiotic and oxygen orders. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-2-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pneumonia-0-2-10-equipment-reason-mechanism-mechanism:pneumonia-0"],"narration":"pneumonia-step-2"},{"title":"Record a respiratory baseline","instruction":"Place the monitoring probe on the virtual patient''s finger. Review the qualitative breathing and oxygenation indicators.","targetId":"equipment:monitor","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-2-5-equipment-monitor-probe-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pneumonia-0-2-5-equipment-chart-probe-0"],"narration":"pneumonia-step-3"},{"title":"Check the medication order","instruction":"Touch the prescription dock with the labeled medicine. Match patient, medicine, route and the supplied order.","targetId":"equipment:prescribed-care","action":5,"toolId":"medication","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-2-5-equipment-prescribed-care-medication-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pneumonia-0-2-5-equipment-monitor-probe-0"],"narration":"pneumonia-step-4"},{"title":"Prepare the prescribed route","instruction":"Join the prepared administration set to its labeled port.","targetId":"equipment:prescribed-care","action":4,"toolId":"connector","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-2-4-equipment-prescribed-care-connector-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pneumonia-0-2-5-equipment-prescribed-care-medication-0"],"narration":"pneumonia-step-5"},{"title":"Administer the ordered treatment","instruction":"Seat the checked medicine in its administration port. Hold the trigger to represent the prescribed administration.","targetId":"equipment:prescribed-care","action":6,"toolId":"medication","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-2-6-equipment-prescribed-care-medication-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pneumonia-0-2-4-equipment-prescribed-care-connector-0"],"narration":"pneumonia-step-6"},{"title":"Apply the oxygen order","instruction":"Fit the support mask to the virtual patient. The case uses its supplied oxygen order.","targetId":"equipment:mouthpiece","action":6,"toolId":"oxygen","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-2-6-equipment-mouthpiece-oxygen-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pneumonia-0-2-6-equipment-prescribed-care-medication-0"],"narration":"pneumonia-step-7"},{"title":"Recheck respiratory support","instruction":"Return the monitoring probe to the finger. Compare the response with baseline.","targetId":"equipment:monitor","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-2-5-equipment-monitor-probe-1","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pneumonia-0-2-6-equipment-mouthpiece-oxygen-0"],"narration":"pneumonia-step-8"},{"title":"Predict the structural response","instruction":"Before reassessing the patient, place the cutaway showing the expected anatomical response in the dock. Model changes are illustrative; improvement does not prove clinical recovery.","targetId":"equipment:reason-response","action":10,"toolId":"response:improved","equipmentState":"placed","choices":[{"id":"response:improved","label":"Gradual clearing","model":"pneumonia","response":1,"rationale":"The represented treatment addresses this anatomical mechanism."},{"id":"response:unchanged","label":"Unchanged anatomy","model":"pneumonia","response":0,"rationale":"An unchanged model does not show the intended structural response. Reassess the mechanism and treatment."},{"id":"response:other","label":"Restricted valve opening","model":"aortic-stenosis","response":1,"rationale":"This is a different compartment or mechanism. Match the response to the anatomy actually treated."}],"explanation":"Inflammatory air-space changes improve over time; oxygen support alone does not eliminate infection.","criticalOnWrong":false,"id":"pneumonia-0-2-10-equipment-reason-response-response:improved-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["pneumonia-0-2-5-equipment-monitor-probe-1"],"narration":"pneumonia-step-9"},{"title":"Review the follow-up timeline","instruction":"Probe the affected lobe. Watch the days-and-weeks timeline; recovery is gradual.","targetId":"MAL_RLL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-2-8-mal_rll-probe-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pneumonia-0-2-10-equipment-reason-response-response:improved-0"],"narration":"pneumonia-step-10"}],"protectedIds":["REC_Right_Phrenic_nerve"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('pleural-effusion-0-0', '2026.10.2', '{"id":"pleural-effusion-0-0","unitId":"pleural-effusion","version":"2026.10.2","mode":0,"difficulty":0,"ordered":true,"briefing":"A symptomatic right pleural collection has been selected for ultrasound-guided therapeutic aspiration. One coached step and one needed instrument are shown at a time.","debrief":"Fluid removal relieves compression in this case. Monitor symptoms and the puncture site; send the planned sample and investigate why fluid accumulated. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the pleural collection","instruction":"Select the right parietal pleura. Identify fluid outside the lower lung.","targetId":"REC_Right_Parietal_Pleura","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-0-3-rec_right_parietal_pleura-hand-0","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"pleural-effusion-step-0"},{"title":"Explain the anatomical mechanism","instruction":"Inspect the specimen and three cutaways. Grip the mechanism that explains this case and release it into the patient-plan dock.","targetId":"equipment:reason-mechanism","action":10,"toolId":"mechanism:pleural-effusion","equipmentState":"placed","choices":[{"id":"mechanism:pleural-effusion","label":"Pleural fluid","model":"pleural-effusion","response":0,"rationale":"Compare this cutaway with the observed anatomy. Fluid outside the lung compresses its surrounding pleural compartment."},{"id":"mechanism:asthma","label":"Narrowed airway","model":"asthma","response":0,"rationale":"Compare this cutaway with the observed anatomy. Airway narrowing restricts airflow; it is not a pleural collection."},{"id":"mechanism:coronary-disease","label":"Narrowed coronary lumen","model":"coronary-disease","response":0,"rationale":"Compare this cutaway with the observed anatomy. Coronary plaque limits the vessel lumen and myocardial blood supply."}],"explanation":"Fluid outside the lung compresses its surrounding pleural compartment.","criticalOnWrong":false,"id":"pleural-effusion-0-0-10-equipment-reason-mechanism-mechanism:pleural-effusion-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["pleural-effusion-0-0-3-rec_right_parietal_pleura-hand-0"],"narration":"pleural-effusion-step-1"},{"title":"Check the patient and plan","instruction":"Review the aspiration indication and bleeding-risk assessment. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-0-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pleural-effusion-0-0-10-equipment-reason-mechanism-mechanism:pleural-effusion-0"],"narration":"pleural-effusion-step-2"},{"title":"Locate fluid with ultrasound","instruction":"Hold the ultrasound probe at the side-window. Identify fluid above the diaphragm and outside the lung.","targetId":"equipment:pleural-site","action":5,"toolId":"ultrasound","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-0-5-equipment-pleural-site-ultrasound-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pleural-effusion-0-0-5-equipment-chart-probe-0"],"narration":"pleural-effusion-step-3"},{"title":"Prepare the skin","instruction":"Use the swab over the ultrasound-selected window.","targetId":"equipment:pleural-site","action":6,"toolId":"swab","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-0-6-equipment-pleural-site-swab-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pleural-effusion-0-0-5-equipment-pleural-site-ultrasound-0"],"narration":"pleural-effusion-step-4"},{"title":"Represent local anaesthesia","instruction":"Place the checked anaesthetic syringe at the entry target.","targetId":"equipment:pleural-site","action":6,"toolId":"anaesthetic","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-0-6-equipment-pleural-site-anaesthetic-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pleural-effusion-0-0-6-equipment-pleural-site-swab-0"],"narration":"pleural-effusion-step-5"},{"title":"Prepare controlled aspiration","instruction":"Connect the syringe and collection circuit. This case uses controlled aspiration without wall suction.","targetId":"equipment:aspiration","action":4,"toolId":"connector","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-0-4-equipment-aspiration-connector-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pleural-effusion-0-0-6-equipment-pleural-site-anaesthetic-0"],"narration":"pleural-effusion-step-6"},{"title":"Advance the aspiration catheter","instruction":"Follow the short channel above the lower rib. Stop in the fluid; preserve deeper lung and diaphragm.","targetId":"equipment:pleural-end","action":7,"toolId":"aspirator","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-0-7-equipment-pleural-end-aspirator-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["pleural-effusion-0-0-4-equipment-aspiration-connector-0"],"narration":"pleural-effusion-step-7"},{"title":"Begin slow aspiration","instruction":"Hold the aspiration control and watch the fluid fall. A symptom cue will ask you to pause.","targetId":"equipment:pleural-end","action":6,"toolId":"aspirator","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-0-6-equipment-pleural-end-aspirator-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pleural-effusion-0-0-7-equipment-pleural-end-aspirator-0"],"narration":"pleural-effusion-step-8"},{"title":"New chest discomfort during aspiration","instruction":"The patient develops chest discomfort while fluid is being aspirated. Place the next-action symbol into the dock.","targetId":"equipment:reason-safety","action":10,"toolId":"pause-review","equipmentState":"placed","choices":[{"id":"pause-review","label":"Stop and reassess","rationale":"Stop aspiration and assess the new symptom before considering further treatment."},{"id":"continue","label":"Continue draining","rationale":"Continuing despite new chest discomfort is unsafe in this authored case. Stop aspiration and reassess."},{"id":"dismiss","label":"Dismiss the symptom","rationale":"A new symptom during aspiration requires attention. Stop aspiration and reassess."}],"explanation":"Aspiration stops when chest discomfort develops. The next step records the symptom assessment.","criticalOnWrong":true,"id":"pleural-effusion-0-0-10-equipment-reason-safety-pause-review-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["pleural-effusion-0-0-6-equipment-pleural-end-aspirator-0"],"narration":"pleural-effusion-step-9"},{"title":"Stop and check new chest discomfort","instruction":"Release aspiration. Touch the monitoring station with the probe to record the symptom check.","targetId":"equipment:monitor","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-0-5-equipment-monitor-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pleural-effusion-0-0-10-equipment-reason-safety-pause-review-0"],"narration":"pleural-effusion-step-10"},{"title":"Withdraw and dress the site","instruction":"Withdraw the aspiration catheter along the return markers. The dressing is applied after removal.","targetId":"equipment:pleural-withdrawal","action":7,"toolId":"aspirator","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-0-7-equipment-pleural-withdrawal-aspirator-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["pleural-effusion-0-0-5-equipment-monitor-probe-0"],"narration":"pleural-effusion-step-11"},{"title":"Predict the structural response","instruction":"Before reassessing the patient, place the cutaway showing the expected anatomical response in the dock. Model changes are illustrative; improvement does not prove clinical recovery.","targetId":"equipment:reason-response","action":10,"toolId":"response:improved","equipmentState":"placed","choices":[{"id":"response:improved","label":"Less pleural fluid","model":"pleural-effusion","response":1,"rationale":"The represented treatment addresses this anatomical mechanism."},{"id":"response:unchanged","label":"Unchanged anatomy","model":"pleural-effusion","response":0,"rationale":"An unchanged model does not show the intended structural response. Reassess the mechanism and treatment."},{"id":"response:other","label":"Inflamed air spaces","model":"pneumonia","response":1,"rationale":"This is a different compartment or mechanism. Match the response to the anatomy actually treated."}],"explanation":"The model shows the intended anatomical change. Clinical benefit and complications still require reassessment.","criticalOnWrong":false,"id":"pleural-effusion-0-0-10-equipment-reason-response-response:improved-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["pleural-effusion-0-0-7-equipment-pleural-withdrawal-aspirator-0"],"narration":"pleural-effusion-step-12"},{"title":"Review symptoms and the cause","instruction":"Probe the right lower lobe. Compare expansion and review the fluid investigation plan.","targetId":"MAL_RLL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-0-8-mal_rll-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pleural-effusion-0-0-10-equipment-reason-response-response:improved-0"],"narration":"pleural-effusion-step-13"}],"protectedIds":["FMA13295","REC_Right_IC6_Nerve","REC_Right_IC6_Artery","MAL_RLL"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
