ion":"pleural-effusion-step-9"},{"title":"Stop and check new chest discomfort","instruction":"Release aspiration. Touch the monitoring station with the probe to record the symptom check.","targetId":"equipment:monitor","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-5-equipment-monitor-probe-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pleural-effusion-0-2-10-equipment-reason-safety-pause-review-0"],"narration":"pleural-effusion-step-10"},{"title":"Withdraw and dress the site","instruction":"Withdraw the aspiration catheter along the return markers. The dressing is applied after removal.","targetId":"equipment:pleural-withdrawal","action":7,"toolId":"aspirator","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-7-equipment-pleural-withdrawal-aspirator-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0.95,"prerequisites":["pleural-effusion-0-2-5-equipment-monitor-probe-0"],"narration":"pleural-effusion-step-11"},{"title":"Predict the structural response","instruction":"Before reassessing the patient, place the cutaway showing the expected anatomical response in the dock. Model changes are illustrative; improvement does not prove clinical recovery.","targetId":"equipment:reason-response","action":10,"toolId":"response:improved","equipmentState":"placed","choices":[{"id":"response:improved","label":"Less pleural fluid","model":"pleural-effusion","response":1,"rationale":"The represented treatment addresses this anatomical mechanism."},{"id":"response:unchanged","label":"Unchanged anatomy","model":"pleural-effusion","response":0,"rationale":"An unchanged model does not show the intended structural response. Reassess the mechanism and treatment."},{"id":"response:other","label":"Inflamed air spaces","model":"pneumonia","response":1,"rationale":"This is a different compartment or mechanism. Match the response to the anatomy actually treated."}],"explanation":"The model shows the intended anatomical change. Clinical benefit and complications still require reassessment.","criticalOnWrong":false,"id":"pleural-effusion-0-2-10-equipment-reason-response-response:improved-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["pleural-effusion-0-2-7-equipment-pleural-withdrawal-aspirator-0"],"narration":"pleural-effusion-step-12"},{"title":"Review symptoms and the cause","instruction":"Probe the right lower lobe. Compare expansion and review the fluid investigation plan.","targetId":"MAL_RLL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-8-mal_rll-probe-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pleural-effusion-0-2-10-equipment-reason-response-response:improved-0"],"narration":"pleural-effusion-step-13"}],"protectedIds":["FMA13295","REC_Right_IC6_Nerve","REC_Right_IC6_Artery","MAL_RLL"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('aortic-stenosis-0-0', '2026.10.2', '{"id":"aortic-stenosis-0-0","unitId":"aortic-stenosis","version":"2026.10.2","mode":0,"difficulty":0,"ordered":true,"briefing":"A heart team has selected transfemoral TAVI for severe aortic stenosis in a fictional adult. One coached step and one needed instrument are shown at a time.","debrief":"The replacement opens within the native valve. Continue rhythm, valve and groin-site monitoring; watch for leakage, bleeding, stroke symptoms and conduction problems. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the restricted valve","instruction":"Select the anterior aortic cusp. Watch the reduced opening in the cutaway.","targetId":"FMA7253","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-3-fma7253-hand-0","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"aortic-stenosis-step-0"},{"title":"Explain the anatomical mechanism","instruction":"Inspect the specimen and three cutaways. Grip the mechanism that explains this case and release it into the patient-plan dock.","targetId":"equipment:reason-mechanism","action":10,"toolId":"mechanism:aortic-stenosis","equipmentState":"placed","choices":[{"id":"mechanism:aortic-stenosis","label":"Restricted valve opening","model":"aortic-stenosis","response":0,"rationale":"Compare this cutaway with the observed anatomy. Restricted aortic cusps obstruct forward flow from the left ventricle."},{"id":"mechanism:pneumothorax","label":"Pleural air","model":"pneumothorax","response":0,"rationale":"Compare this cutaway with the observed anatomy. Air in the pleural space separates the lung from the chest wall."},{"id":"mechanism:asthma","label":"Narrowed airway","model":"asthma","response":0,"rationale":"Compare this cutaway with the observed anatomy. Airway narrowing restricts airflow; it is not a pleural collection."}],"explanation":"Restricted aortic cusps obstruct forward flow from the left ventricle.","criticalOnWrong":false,"id":"aortic-stenosis-0-0-10-equipment-reason-mechanism-mechanism:aortic-stenosis-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-3-fma7253-hand-0"],"narration":"aortic-stenosis-step-1"},{"title":"Check the patient and plan","instruction":"Review the heart-team decision and the planned CT-sized device. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-10-equipment-reason-mechanism-mechanism:aortic-stenosis-0"],"narration":"aortic-stenosis-step-2"},{"title":"Prepare femoral access","instruction":"Use the swab at the groin target. Local anaesthesia and access preparation are represented.","targetId":"equipment:femoral-access","action":6,"toolId":"swab","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-6-equipment-femoral-access-swab-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-5-equipment-chart-probe-0"],"narration":"aortic-stenosis-step-3"},{"title":"Prepare the delivery system","instruction":"Connect the device handle to the femoral sheath port.","targetId":"equipment:valve-system","action":4,"toolId":"connector","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-4-equipment-valve-system-connector-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-6-equipment-femoral-access-swab-0"],"narration":"aortic-stenosis-step-4"},{"title":"Follow the aorta to the valve","instruction":"Follow femoral, iliac, abdominal aorta, descending aorta, arch and ascending aorta markers to the valve.","targetId":"equipment:aortic-valve","action":7,"toolId":"guidewire","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-7-equipment-aortic-valve-guidewire-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["aortic-stenosis-0-0-4-equipment-valve-system-connector-0"],"narration":"aortic-stenosis-step-5"},{"title":"Align the replacement valve","instruction":"Place the delivery tip across the native valve. Keep the coronary openings unobstructed.","targetId":"equipment:aortic-valve","action":5,"toolId":"valve","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-5-equipment-aortic-valve-valve-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-7-equipment-aortic-valve-guidewire-0"],"narration":"aortic-stenosis-step-6"},{"title":"Deploy inside the native valve","instruction":"Activate the selected self-expanding replacement. The old cusps remain around its scaffold.","targetId":"equipment:aortic-valve","action":6,"toolId":"valve","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-6-equipment-aortic-valve-valve-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-5-equipment-aortic-valve-valve-0"],"narration":"aortic-stenosis-step-7"},{"title":"Check position and forward flow","instruction":"Use the assessment pointer at the implanted valve. Review opening, leakage and the coronary relationship.","targetId":"equipment:aortic-valve","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-5-equipment-aortic-valve-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-6-equipment-aortic-valve-valve-0"],"narration":"aortic-stenosis-step-8"},{"title":"Withdraw the delivery system","instruction":"Return the delivery handle along the withdrawal path, leaving the replacement in place.","targetId":"equipment:valve-withdrawal","action":7,"toolId":"valve","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-7-equipment-valve-withdrawal-valve-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["aortic-stenosis-0-0-5-equipment-aortic-valve-probe-0"],"narration":"aortic-stenosis-step-9"},{"title":"Close and inspect femoral access","instruction":"Place the closure dressing at the groin site and inspect the access model.","targetId":"equipment:femoral-access","action":6,"toolId":"dressing","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-6-equipment-femoral-access-dressing-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-7-equipment-valve-withdrawal-valve-0"],"narration":"aortic-stenosis-step-10"},{"title":"Predict the structural response","instruction":"Before reassessing the patient, place the cutaway showing the expected anatomical response in the dock. Model changes are illustrative; improvement does not prove clinical recovery.","targetId":"equipment:reason-response","action":10,"toolId":"response:improved","equipmentState":"placed","choices":[{"id":"response:improved","label":"Replacement opens","model":"aortic-stenosis","response":1,"rationale":"The represented treatment addresses this anatomical mechanism."},{"id":"response:unchanged","label":"Unchanged anatomy","model":"aortic-stenosis","response":0,"rationale":"An unchanged model does not show the intended structural response. Reassess the mechanism and treatment."},{"id":"response:other","label":"Pleural fluid","model":"pleural-effusion","response":1,"rationale":"This is a different compartment or mechanism. Match the response to the anatomy actually treated."}],"explanation":"The model shows the intended anatomical change. Clinical benefit and complications still require reassessment.","criticalOnWrong":false,"id":"aortic-stenosis-0-0-10-equipment-reason-response-response:improved-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-6-equipment-femoral-access-dressing-0"],"narration":"aortic-stenosis-step-11"},{"title":"Review valve and rhythm follow-up","instruction":"Probe the aortic cusp. Check the represented forward flow and post-procedure monitoring plan.","targetId":"FMA7253","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-8-fma7253-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-10-equipment-reason-response-response:improved-0"],"narration":"aortic-stenosis-step-12"}],"protectedIds":["FMA50040","FMA50039"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('aortic-stenosis-0-1', '2026.10.2', '{"id":"aortic-stenosis-0-1","unitId":"aortic-stenosis","version":"2026.10.2","mode":0,"difficulty":1,"ordered":true,"briefing":"A heart team has selected transfemoral TAVI for severe aortic stenosis in a fictional adult. Use the findings to plan the sequence; most placement cues are removed.","debrief":"The replacement opens within the native valve. Continue rhythm, valve and groin-site monitoring; watch for leakage, bleeding, stroke symptoms and conduction problems. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the restricted valve","instruction":"Select the anterior aortic cusp. Watch the reduced opening in the cutaway.","targetId":"FMA7253","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-1-3-fma7253-hand-0","essential":true,"weight":1,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"aortic-stenosis-step-0"},{"title":"Explain the anatomical mechanism","instruction":"Inspect the specimen and three cutaways. Grip the mechanism that explains this case and release it into the patient-plan dock.","targetId":"equipment:reason-mechanism","action":10,"toolId":"mechanism:aortic-stenosis","equipmentState":"placed","choices":[{"id":"mechanism:aortic-stenosis","label":"Restricted valve opening","model":"aortic-stenosis","response":0,"rationale":"Compare this cutaway with the observed anatomy. Restricted aortic cusps obstruct forward flow from the left ventricle."},{"id":"mechanism:pneumothorax","label":"Pleural air","model":"pneumothorax","response":0,"rationale":"Compare this cutaway with the observed anatomy. Air in the pleural space separates the lung from the chest wall."},{"id":"mechanism:asthma","label":"Narrowed airway","model":"asthma","response":0,"rationale":"Compare this cutaway with the observed anatomy. Airway narrowing restricts airflow; it is not a pleural collection."}],"explanation":"Restricted aortic cusps obstruct forward flow from the left ventricle.","criticalOnWrong":false,"id":"aortic-stenosis-0-1-10-equipment-reason-mechanism-mechanism:aortic-stenosis-0","essential":true,"weight":2,"maxDistance":0.09,"maxAngle":180,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-1-3-fma7253-hand-0"],"narration":"aortic-stenosis-step-1"},{"title":"Check the patient and plan","instruction":"Review the heart-team decision and the planned CT-sized device. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-1-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-1-10-equipment-reason-mechanism-mechanism:aortic-stenosis-0"],"narration":"aortic-stenosis-step-2"},{"title":"Prepare femoral access","instruction":"Use the swab at the groin target. Local anaesthesia and access preparation are represented.","targetId":"equipment:femoral-access","action":6,"toolId":"swab","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-1-6-equipment-femoral-access-swab-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-1-5-equipment-chart-probe-0"],"narration":"aortic-stenosis-step-3"},{"title":"Prepare the delivery system","instruction":"Connect the device handle to the femoral sheath port.","targetId":"equipment:valve-system","action":4,"toolId":"connector","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-1-4-equipment-valve-system-connector-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-1-6-equipment-femoral-access-swab-0"],"narration":"aortic-stenosis-step-4"},{"title":"Follow the aorta to the valve","instruction":"Follow femoral, iliac, abdominal aorta, descending aorta, arch and ascending aorta markers to the valve.","targetId":"equipment:aortic-valve","action":7,"toolId":"guidewire","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-1-7-equipment-aortic-valve-guidewire-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0.95,"prerequisites":["aortic-stenosis-0-1-4-equipment-valve-system-connector-0"],"narration":"aortic-stenosis-step-5"},{"title":"Align the replacement valve","instruction":"Place the delivery tip across the native valve. Keep the coronary openings unobstructed.","targetId":"equipment:aortic-valve","action":5,"toolId":"valve","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-1-5-equipment-aortic-valve-valve-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-1-7-equipment-aortic-valve-guidewire-0"],"narration":"aortic-stenosis-step-6"},{"title":"Deploy inside the native valve","instruction":"Activate the selected self-expanding replacement. The old cusps remain around its scaffold.","targetId":"equipment:aortic-valve","action":6,"toolId":"valve","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-1-6-equipment-aortic-valve-valve-0","essential":true